def transform(wb):
    ws = wb['Sheet1']
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=ws.max_column):
        for cell in row:
            f = copy(cell.font)
            f.name = '等线'
            cell.font = f
    for r in range(7, 24):
        ncell = ws.cell(row=r, column=14)
        ocell = ws.cell(row=r, column=15)
        pcell = ws.cell(row=r, column=16)
        v = ncell.value
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            if v > 40:
                ncell.value = 40
                ocell.value = round(v - 40, 2)
            else:
                ocell.value = None
        for c in (ncell, ocell, pcell):
            val = c.value
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                if float(val).is_integer():
                    c.number_format = 'General'
                else:
                    c.number_format = '#,##0.##'
            else:
                c.number_format = 'General'
